import { contractDraftSummarySchema } from '@ayvo/types';
import Link from 'next/link';
import { z } from 'zod';
import { buttonClass, Card, Notice } from '@/components/ui';
import { contractsCs as t } from '@/i18n/cs/contracts';
import { apiGetPanel } from '@/lib/api';

/**
 * "Návrhy smluv" at a prospect or on a hotel's card (doc 045 §2): the drafts kept there and the
 * explicit way to prepare one — nothing is generated by opening the page. Its own panel (doc 044
 * U2): if the drafts cannot be read, it says so and the rest of the page works.
 */
export async function ContractDraftsCard({
  prospect,
  hotel,
  canPrepare,
}: {
  prospect?: string;
  hotel?: string;
  canPrepare: boolean;
}) {
  const query = prospect ? { prospect } : { hotel };
  const drafts = await apiGetPanel(
    'admin/contracts/drafts',
    z.array(contractDraftSummarySchema),
    query,
  );
  const prepare = `/sales/contracts/new?${prospect ? `prospect=${prospect}` : `hotel=${hotel}`}`;
  return (
    <Card title={t.title} testId="contract-drafts">
      {drafts.state !== 'ok' ? (
        <Notice tone="warning">{t.unavailable}</Notice>
      ) : drafts.data.length === 0 ? (
        <p className="text-sm text-stone-600">{t.none}</p>
      ) : (
        <ul className="divide-y divide-stone-100 text-sm" data-testid="contract-draft-list">
          {drafts.data.map((d) => (
            <li key={d.code} className="flex flex-wrap items-baseline gap-x-3 gap-y-1 py-2">
              <Link href={`/sales/contracts/${d.code}`} className="font-mono underline">
                {d.code}
              </Link>
              <span className="min-w-0 flex-1 wrap-anywhere">{d.counterpartyName}</span>
              <span className="text-xs text-stone-500">{t.revisionShort(d.currentRevision)}</span>
              {d.removed && (
                <span className="text-xs font-medium text-stone-500">{t.removedBadge}</span>
              )}
            </li>
          ))}
        </ul>
      )}
      {canPrepare && drafts.state === 'ok' && (
        <Link
          href={prepare}
          className={`${buttonClass.secondary} mt-3`}
          data-testid="contract-prepare"
        >
          {t.prepare}
        </Link>
      )}
    </Card>
  );
}
